function priceText(pkg){const q=quoteFor(pkg);return q!=null?`${fmt(q)} ${selectedAsset}`:`Not offered in ${selectedAsset}`;}
function assetTotals(items,getAsset,getAmount){const lines=ASSET_CODES.map(asset=>{const total=items.filter(x=>getAsset(x)===asset).reduce((n,x)=>n+BigInt(getAmount(x)||0),0n);return `<div class="asset-total"><span>${asset}</span><strong>${fmt(total.toString())}</strong></div>`;}).join('');return `<div class="asset-totals">${lines}</div>`;}
