const fmt=v=>BigInt(v??0)%10000n===0n?money(v??'0',2):money(v??'0',6).replace(/0+$/,'');
const decimal=v=>money(v,6).replaceAll(',','').replace(/0+$/,'').replace(/\.$/,'');
