const timestamp=v=>new Date(v).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
function stableJSON(value){
  if(value===null||typeof value!=='object')return JSON.stringify(value);
  if(Array.isArray(value))return '['+value.map(stableJSON).join(',')+']';
  return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+stableJSON(value[k])).join(',')+'}';
}
function fingerprint(value){let h=2166136261;for(const ch of stableJSON(value)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
function newOperationId(){return globalThis.crypto?.randomUUID?.()||`op-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;}
function operationHandle(scope,value){
  const storageKey=PENDING_OP_PREFIX+fingerprint({scope,value});
  let id=null;try{id=localStorage.getItem(storageKey);}catch{}
  if(!id){id=newOperationId();try{localStorage.setItem(storageKey,id);}catch{}}
  return {id,storageKey};
}
function clearOperation(handle){if(!handle)return;try{localStorage.removeItem(handle.storageKey);}catch{}}
