function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4200);}
function readRaw(key){try{return localStorage.getItem(key);}catch{return undefined;}}
function writeRaw(key,value){try{localStorage.setItem(key,value);return true;}catch{return false;}}
function validateState(candidate){assertInvariants(candidate);return candidate;}
function seedAndPersist(){
  const seed=createSeedState();
  validateState(seed);
  const beforeNew=readRaw(STORAGE);
  const beforeOld=readRaw(LEGACY_STORAGE);
  if(beforeNew!==null||beforeOld!==null)throw new Error('Refusing to overwrite existing cache.');
  const serialized=JSON.stringify(seed);
  if(!writeRaw(STORAGE,serialized)){
    memoryOnly=true;
    storageSnapshot=null;
    setTimeout(()=>toast('Storage write failed. This session remains in memory only.',true),0);
    return seed;
  }
  storageSnapshot=serialized;
  memoryOnly=false;
  return seed;
}
async function load(){
  if(EMBEDDED){
    if(memoryOnly&&state){validateState(state);return;}
    recoveryRaw=null;recoveryKey=null;recoveryError=null;memoryOnly=false;
    state=undefined;
    let rawNew;
    try{rawNew=localStorage.getItem(STORAGE);}
    catch(err){
      memoryOnly=true;
      const seed=createSeedState();
      validateState(seed);
      state=seed;
      storageSnapshot=null;
      try{actorId=localStorage.getItem(STORAGE+'-actor')||localStorage.getItem(LEGACY_STORAGE+'-actor')||'buyer';}catch{}
      if(!user(actorId))actorId='buyer';
      setTimeout(()=>toast('Storage is unavailable. This session remains in memory only.',true),0);
      return;
    }
    if(rawNew!==null){
      let parsed;
      try{parsed=JSON.parse(rawNew);}
      catch(err){
        recoveryRaw=rawNew;recoveryKey=STORAGE;recoveryError=err;
        throw new Error('Saved sandbox data is not valid JSON.');
      }
      let migrated;
      try{migrated=migrateState(parsed);validateState(migrated);}
      catch(err){
        recoveryRaw=rawNew;recoveryKey=STORAGE;recoveryError=err;
        throw new Error('Saved sandbox data failed validation.');
      }
      state=migrated;
      storageSnapshot=rawNew;
      try{actorId=localStorage.getItem(STORAGE+'-actor')||localStorage.getItem(LEGACY_STORAGE+'-actor')||'buyer';}catch{}
      if(!user(actorId))actorId='buyer';
      return;
    }
    // new absent, try legacy
    let rawOld;
    try{rawOld=localStorage.getItem(LEGACY_STORAGE);}catch{rawOld=undefined;}
    if(rawOld===undefined){
      memoryOnly=true;
      const seed=createSeedState();
      validateState(seed);
      state=seed;
      storageSnapshot=null;
      try{actorId=localStorage.getItem(STORAGE+'-actor')||localStorage.getItem(LEGACY_STORAGE+'-actor')||'buyer';}catch{}
      if(!user(actorId))actorId='buyer';
      setTimeout(()=>toast('Storage is unavailable. This session remains in memory only.',true),0);
      return;
    }
    if(rawOld!==null){
      let parsedOld;
      try{parsedOld=JSON.parse(rawOld);}
      catch(err){
        recoveryRaw=rawOld;recoveryKey=LEGACY_STORAGE;recoveryError=err;
        throw new Error('Legacy sandbox data is not valid JSON.');
      }
      let migrated;
      try{migrated=migrateState(parsedOld);validateState(migrated);}
      catch(err){
        recoveryRaw=rawOld;recoveryKey=LEGACY_STORAGE;recoveryError=err;
        throw new Error('Legacy sandbox data failed validation.');
      }
      const beforeNew=readRaw(STORAGE);
      const beforeOld=readRaw(LEGACY_STORAGE);
      if(beforeNew!==null||beforeOld!==rawOld){
        // concurrent change; re-read new
        const recheck=readRaw(STORAGE);
        if(recheck!==null){
          let reparsed;
          try{reparsed=JSON.parse(recheck);}catch(err){recoveryRaw=recheck;recoveryKey=STORAGE;recoveryError=err;throw new Error('Concurrent cache change detected.');}
          let remigrated;
          try{remigrated=migrateState(reparsed);validateState(remigrated);}catch(err){recoveryRaw=recheck;recoveryKey=STORAGE;recoveryError=err;throw new Error('Concurrent cache change detected.');}
          state=remigrated;storageSnapshot=recheck;
          try{actorId=localStorage.getItem(STORAGE+'-actor')||localStorage.getItem(LEGACY_STORAGE+'-actor')||'buyer';}catch{}
          if(!user(actorId))actorId='buyer';
          return;
        }
        throw new Error('Another tab changed storage. Refresh before retrying.');
      }
      const serialized=JSON.stringify(migrated);
      if(!writeRaw(STORAGE,serialized)){
        // quota failure: keep in memory
        memoryOnly=true;
        state=migrated;
        storageSnapshot=null;
        try{actorId=localStorage.getItem(STORAGE+'-actor')||localStorage.getItem(LEGACY_STORAGE+'-actor')||'buyer';}catch{}
        if(!user(actorId))actorId='buyer';
        setTimeout(()=>toast('Storage write failed. This session remains in memory only.',true),0);
        return;
      }
      storageSnapshot=serialized;
      state=migrated;
      try{actorId=localStorage.getItem(STORAGE+'-actor')||localStorage.getItem(LEGACY_STORAGE+'-actor')||'buyer';}catch{}
      if(!user(actorId))actorId='buyer';
      return;
    }
    // both absent: fresh seed
    const seed=seedAndPersist();
    state=seed;
    try{actorId=localStorage.getItem(STORAGE+'-actor')||localStorage.getItem(LEGACY_STORAGE+'-actor')||'buyer';}catch{}
    if(!user(actorId))actorId='buyer';
    return;
  }
  const response=await fetch('/api/state',{cache:'no-store'});
  if(!response.ok)throw new Error('Could not load the local sandbox. Start it with npm start.');
  const out=await response.json();
  state=migrateState(out.state);
  validateState(state);
  accountFeatureFlags={accountCreation:false,walletSignIn:false};
  try{
    const capability=await fetch('/api/payments/config',{cache:'no-store'});
    if(capability.ok){
      const config=await capability.json();
      const flags=config?.featureFlags||{};
      accountFeatureFlags={accountCreation:flags.accountCreation===true,walletSignIn:flags.walletSignIn===true};
    }
  }catch{accountFeatureFlags={accountCreation:false,walletSignIn:false};}
  try{actorId=localStorage.getItem(STORAGE+'-actor')||localStorage.getItem(LEGACY_STORAGE+'-actor')||'buyer';}catch{}
  if(!user(actorId))actorId='buyer';
}
async function command(type,payload,idempotencyKey=newOperationId()){
  if(EMBEDDED){
    if(!memoryOnly){
      let current;
      try{current=localStorage.getItem(STORAGE);}catch{current=undefined;}
      if(current===undefined){
        memoryOnly=true;
      }else if(current!==storageSnapshot){
        throw new Error('Another tab changed the saved sandbox. Refresh before retrying.');
      }
    }
    const out=applyCommand(state,actorId,type,payload);
    validateState(out.state);
    if(!memoryOnly){
      const serialized=JSON.stringify(out.state);
      let ok=false;
      try{localStorage.setItem(STORAGE,serialized);ok=true;}catch{ok=false;}
      if(!ok){
        memoryOnly=true;
        state=out.state;
        storageSnapshot=null;
        toast('Storage write failed. This session remains in memory only.',true);
        return out.result;
      }
      storageSnapshot=serialized;
    }
    state=out.state;
    return out.result;
  }
  const response=await fetch('/api/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actorId,command:type,payload,idempotencyKey})});
  const out=await response.json();
  if(!response.ok)throw new Error(out.error||'Command failed.');
  state=migrateState(out.state);
  validateState(state);
  return out.result;
}
