async function copySandboxDealLink(id){const base=location.href.split('#')[0]||location.href;const link=`${base}#/deal/${encodeURIComponent(id)}`;let copied=false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(link);copied=true;}}catch{}if(!copied){const input=document.createElement('textarea');input.value=link;input.setAttribute('readonly','');input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();try{copied=document.execCommand('copy');}catch{}input.remove();}toast(copied?'Copied a sandbox-only deal link.':'Link ready: use the browser address bar to share this sandbox deal.',!copied);}
