document.addEventListener('submit',async event=>{
 const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(busy)return;
 const values=Object.fromEntries(new FormData(form));
 if(form.dataset.form==='search'){navigate('#/explore'+(values.query.trim()?'?query='+encodeURIComponent(values.query.trim()):''));return;}
 if(form.dataset.form==='filter'){const {q}=route();if(values.max)q.set('max',values.max);else q.delete('max');q.set('sort',values.sort);navigate('#/explore?'+q.toString());return;}
 busy=true;const submit=form.querySelector('button[type="submit"]')||form.querySelector('button');if(submit)submit.disabled=true;
  try{
  const handle=operationHandle('modal:'+actorId+':'+stableJSON(modalContext||{}),values);form.__operationHandle=handle;
   if(form.dataset.form==='modal')await submitModal(form,handle.id);
   if(form.dataset.form==='message'){const o=state.orders.find(o=>o.id===form.dataset.order);await command('add_message',{orderId:o.id,expectedVersion:o.version,text:values.text},handle.id);clearOperation(handle);render();toast('Message stored in the local deal room.');}
 }catch(error){const errorBox=form.querySelector('.form-error');if(errorBox){errorBox.textContent=error.message;errorBox.scrollIntoView({block:'nearest'});}toast(error.message,true);}
 finally{busy=false;if(submit?.isConnected)submit.disabled=false;}
});
window.addEventListener('hashchange',()=>{U.closeJupiter();closeModal();if(state===undefined)return;render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',event=>{
  if(event.key!==STORAGE)return;
  if(event.newValue===storageSnapshot)return;
  toast('Another tab changed the saved sandbox. Refresh before retrying.',true);
});
function renderRecovery(){
  const raw=recoveryRaw;
  $('#app').innerHTML=`<main id="main" class="container mt40"><div class="panel danger"><h1>Saved sandbox data needs attention.</h1><p class="small mt20">No data has been replaced. The saved cache could not be validated. You can export the original raw data, retry loading, or reset the demo cache.</p><p class="small mt12">${e(recoveryError?.message||'Unknown error')}</p><div class="row wrap mt20">${button('Retry','retry-init','','btn-primary')}${button('Export saved data','recovery-export','','btn-small')}${EMBEDDED&&raw!==null?button('Reset demo','recovery-reset','','btn-danger btn-small'):''}</div></div></main>`;
}
function recoveryExport(){
  if(recoveryRaw===null)return toast('No raw data available.',true);
  const blob=new Blob([recoveryRaw],{type:'application/json'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='escrow-global-recovery.json';a.click();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function recoveryReset(){
  if(!EMBEDDED||recoveryRaw===null)return;
  if(!window.confirm('Reset the demo cache? Existing cache will be backed up to a recovery key. Legacy cache is untouched.'))return;
  const currentRaw=readRaw(recoveryKey);
  if(currentRaw!==recoveryRaw){toast('Cache changed since error. Refresh before resetting.',true);return;}
  if(recoveryKey===LEGACY_STORAGE&&readRaw(STORAGE)!==null){toast('New cache appeared. Refresh before resetting.',true);return;}
  const backupKey=`${STORAGE}-recovery-${Date.now()}`;
  if(recoveryRaw===null||recoveryRaw===undefined){toast('Nothing to back up.',true);return;}
  if(!writeRaw(backupKey,recoveryRaw)){toast('Backup failed. Nothing was deleted.',true);return;}
  const seed=createSeedState();
  validateState(seed);
  const recheckCurrent=readRaw(recoveryKey);
  const recheckNew=readRaw(STORAGE);
  if(recheckCurrent!==recoveryRaw){toast('Cache changed during reset. Aborted.',true);return;}
  if(recoveryKey===LEGACY_STORAGE&&recheckNew!==null){toast('New cache appeared during reset. Aborted.',true);return;}
  const serialized=JSON.stringify(seed);
  if(!writeRaw(STORAGE,serialized)){toast('Could not write fresh cache. Nothing was deleted.',true);return;}
  storageSnapshot=serialized;
  state=seed;
  memoryOnly=false;
  recoveryRaw=null;recoveryKey=null;recoveryError=null;
  render();
  if(typeof U!=='undefined'&&U&&typeof U.init==='function'){U.init();}
  else{init();}
}
async function init(){
  try{
    await load();
    render();
    U.init();
  }catch(error){
    if(EMBEDDED&&recoveryRaw!==null){
      renderRecovery();
    }else{
      $('#app').innerHTML=`<main id="main" class="container mt40"><div class="panel danger"><h1>Saved sandbox data needs attention.</h1><p class="small mt20">No data has been replaced. ${e(error.message)}</p><div class="row wrap mt20">${button('Retry','retry-init','','btn-primary')}</div></div></main>`;
    }
  }
}
